func XQuit(tls *libc.TLS, msg uintptr) {
	// Shutdown VL early to return to text mode.
	XVL_Shutdown(tls)
	if !(msg != 0) || !(**(**int8)(__ccgo_up(msg)) != 0) {
		if XUS_TerminalOk(tls) != 0 && !(quitting != 0) {
			quitting = libc.BoolUint8(true1 != 0)
			XCA_CacheGrChunk(tls, int32(XCK_VAR_GetInt(tls, __ccgo_ts, 0)))
			// There is a 7-byte BSAVE header at the start of the
			// chunk, and we don't want to print the last row, as
			// originally it would be overwritten by DOS anyway.
			XUS_PrintB8000Text(tls, Xca_graphChunks[XCK_VAR_GetInt(tls, __ccgo_ts, 0)]+uintptr(7), libc.Int32FromInt32(2000)-libc.Int32FromInt32(80))
		} else {
			XCK_Cross_LogMessage(tls, int32(CK_LOG_MSG_NORMAL), __ccgo_ts+19, 0)
		}
		XCK_ShutdownID(tls)
		runtimeExit(tls, 0)
	} else {
		XCK_Cross_puts(tls, msg)
		XCK_ShutdownID(tls)
		runtimeExit(tls, -int32(1))
	}
}

// Avoid trying to re-print the order screen if caching it failed.
var quitting uint8

func XQuitF(tls *libc.TLS, msg uintptr, va uintptr) {
	bp := tls.Alloc(512)
	defer tls.Free(512)
	var args va_list
	var _ /* msg_buf at bp+0 */ [512]int8
	_ = args
	args = va
	libc.X__builtin_vsnprintf(tls, bp, uint64(512), msg, args)
	_ = args
	XQuit(tls, bp)
}

