	numDictEntries = int32(1)<<dictBits - int32(CA_LZW_SPECIAL_ENTRIES)
	// Note that this could be _very_ big: *.aslev files have up to 24-bit dict
	// entries, so need 256 _megs_ of space for a full dictionary. We probably
	// should grow this lazily.
	XMM_GetPtr(tls, bp+8, libc.Uint64FromInt32(numDictEntries)*uint64(16))
	XMM_SetLock(tls, bp+8, libc.BoolUint8(true1 != 0))
	maxDictEntry = int32(CA_LZW_SPECIAL_ENTRIES)
	code = uint32(CA_LZW_ERROR)
