							dPtr = dPtr + 1
							**(**uint8_t)(__ccgo_up(v1)) = **(**uint8_t)(__ccgo_up((**(**CA_LZW_DictEntry)(__ccgo_up(**(**uintptr)(__ccgo_up(bp + 8)) + uintptr(prevCode-uint32(CA_LZW_SPECIAL_ENTRIES))*16))).FfirstByte))
