var ca_gr_huffdict uintptr

var ca_graphHandle FS_File //File Pointer for ?GAGRAPH file.

// C documentation
//
//	//Get the offset of a (compressed) chunk in the ?GAGRAPH file.
func XCAL_GetGrChunkStart(tls *libc.TLS, chunk int32) (r int64) {
	var offset int32
	var value int64
	_, _ = offset, value
	offset = chunk * int32(3)
	if offset >= Xca_graphHeadSize {
		return int64(-int32(1))
	}
	value = int64(libc.Int32FromUint8(**(**uint8_t)(__ccgo_up(Xca_graphStarts + uintptr(offset)))) | libc.Int32FromUint8(**(**uint8_t)(__ccgo_up(Xca_graphStarts + uintptr(offset+int32(1)))))<<int32(8) | libc.Int32FromUint8(**(**uint8_t)(__ccgo_up(Xca_graphStarts + uintptr(offset+int32(2)))))<<int32(16))
	if value == int64(0xffffff) {
		return int64(-int32(1))
	}
	return value
}

func XCAL_GetGrChunkExpLength(tls *libc.TLS, chunk int32) (r int32) {
	var chunkExpandedLength uint32_t
	_ = chunkExpandedLength
	if chunk >= libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles8) && chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffBinaries) {
		if chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles8m) {
			chunkExpandedLength = libc.Uint32FromInt32(int32(32) * libc.Int32FromUint16(Xca_gfxInfoE.FnumTiles8))
		} else {
			if chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles16) {
				chunkExpandedLength = libc.Uint32FromInt32(int32(40) * libc.Int32FromUint16(Xca_gfxInfoE.FnumTiles8m))
			} else {
				if chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles16m) {
					chunkExpandedLength = uint32(128)
				} else {
					if chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles32) {
						chunkExpandedLength = libc.Uint32FromInt32(libc.Int32FromInt32(40) * libc.Int32FromInt32(4))
					} else {
						if chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles32m) {
							chunkExpandedLength = libc.Uint32FromInt32(libc.Int32FromInt32(32) * libc.Int32FromInt32(16))
						} else {
							chunkExpandedLength = libc.Uint32FromInt32(libc.Int32FromInt32(40) * libc.Int32FromInt32(16))
						}
					}
				}
			}
		}
	} else {
		//TODO: Work out how to return this. Struct?
		//fseek(ca_graphHandle, CAL_GetGrChunkStart(chunk), SEEK_SET);
		//fread(&chunkExpandedLength,4,1,ca_graphHandle);
		return 0
	}
	return libc.Int32FromUint32(chunkExpandedLength)
}

func XCAL_GetGrChunkCompLength(tls *libc.TLS, chunk int32) (r int32) {
	var nextChunk, sizeOffset int32
	_, _ = nextChunk, sizeOffset
	nextChunk = chunk + int32(1)
	sizeOffset = 0
	if chunk < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles8) && chunk >= libc.Int32FromUint16(Xca_gfxInfoE.FoffBinaries) {
		sizeOffset = int32(4)
	}
	if nextChunk*int32(3) >= Xca_graphHeadSize {
		return int32(int64(Xca_graphFileSize) - XCAL_GetGrChunkStart(tls, chunk) - int64(sizeOffset))
	}
	for XCAL_GetGrChunkStart(tls, nextChunk) == int64(-int32(1)) {
		nextChunk = nextChunk + 1
	}
	return int32(XCAL_GetGrChunkStart(tls, nextChunk) - XCAL_GetGrChunkStart(tls, chunk) - int64(sizeOffset))
}

func XCA_LockGrChunk(tls *libc.TLS, chunk int32) {
	XMM_SetLock(tls, uintptr(unsafe.Pointer(&Xca_graphChunks))+uintptr(chunk)*8, libc.BoolUint8(true1 != 0))
}

