func XRF_Refresh(tls *libc.TLS) {
	var x, y int32
	_, _ = x, y
	XRFL_AnimateTiles(tls)
	//TODO: Work out how to do scrolling before using this
	XRFL_UpdateTiles(tls)
	XRFL_ProcessSpriteErasers(tls)
	XRFL_DrawSpriteList(tls)
	// No blocks should be dirty on this page after the frame has been rendered.
	y = 0
	for {
		if !(y < int32(RF_BUFFER_HEIGHT_TILES)) {
			break
		}
		x = 0
		for {
			if !(x < int32(RF_BUFFER_WIDTH_TILES)) {
				break
			}
			XRFL_MarkBlockDirty(tls, x, y, 0, XVL_GetActiveBuffer(tls))
			goto _2
		_2:
			;
			x = x + 1
		}
		goto _1
	_1:
		;
		y = y + 1
	}
	if Xrf_drawFunc != 0 {
		(*(*func(*libc.TLS))(unsafe.Pointer(&struct{ uintptr }{Xrf_drawFunc})))(tls)
	}
	// 0xef for the X-direction to match EGA keen's 2px horz scrolling.
	XVL_SetScrollCoords(tls, Xrf_scrollXUnit&int32(0xef)>>int32(G_P_SHIFT), Xrf_scrollYUnit&int32(0xff)>>int32(G_P_SHIFT))
	XVL_SwapOnNextPresent(tls)
	XVL_Present(tls)
	XRFL_CalcTics(tls)
}

