// Coords in tile8s

func XUS_DrawWindow(tls *libc.TLS, x int32, y int32, w int32, h int32) {
	var borderH, borderW, borderX, borderY, i, i1 int32
	_, _, _, _, _, _ = borderH, borderW, borderX, borderY, i, i1
	us_windowX = int16(x * int32(8))
	us_windowY = int16(y * int32(8))
	us_windowW = int16(w * int32(8))
	us_windowH = int16(h * int32(8))
	borderX = int32(us_windowX) - int32(8)
	borderY = int32(us_windowY) - int32(8)
	borderW = int32(us_windowW) + int32(8)
	borderH = int32(us_windowH) + int32(8)
	us_printX = us_windowX
	us_printY = us_windowY
	XUS_ClearWindow(tls)
	XVHB_DrawTile8M(tls, borderX, borderY, 0)                        //Top Left Corner
	XVHB_DrawTile8M(tls, borderX, borderY+borderH, int32(6))         //Bottom Left Corner
	XVHB_DrawTile8M(tls, borderX+borderW, borderY, int32(2))         //Top Right Corner
	XVHB_DrawTile8M(tls, borderX+borderW, borderY+borderH, int32(8)) //Bottom Right Corner
	// Draw Horizontal sides
	i = borderX + int32(8)
	for {
		if !(i <= borderX+borderW-int32(8)) {
			break
		}
		XVHB_DrawTile8M(tls, i, borderY, int32(1))         //Top row
		XVHB_DrawTile8M(tls, i, borderY+borderH, int32(7)) //Bottom Row
		goto _1
	_1:
		;
		i = i + int32(8)
	}
	//Draw Vertical sides
	i1 = borderY + int32(8)
	for {
		if !(i1 <= borderY+borderH-int32(8)) {
			break
		}
		XVHB_DrawTile8M(tls, borderX, i1, int32(3))         //Left col
		XVHB_DrawTile8M(tls, borderX+borderW, i1, int32(5)) //Right col
		goto _2
	_2:
		;
		i1 = i1 + int32(8)
	}
}

func XUS_CenterWindow(tls *libc.TLS, w int32, h int32) {
	var maxXtile, maxYtile int32
	_, _ = maxXtile, maxYtile
	maxXtile = libc.Int32FromInt32(US_WINDOW_MAX_X) / libc.Int32FromInt32(8)
	maxYtile = libc.Int32FromInt32(US_WINDOW_MAX_Y) / libc.Int32FromInt32(8)
	XUS_DrawWindow(tls, (maxXtile-w)/int32(2), (maxYtile-h)/int32(2), w, h)
}

// C documentation
//
//	//	US_SaveWindow() - Saves the current window parms into a record for later restoration
func XUS_SaveWindow(tls *libc.TLS, win uintptr) {
	(*US_WindowRec)(unsafe.Pointer(win)).Fx = XUS_GetWindowX(tls)
	(*US_WindowRec)(unsafe.Pointer(win)).Fy = XUS_GetWindowY(tls)
	(*US_WindowRec)(unsafe.Pointer(win)).Fw = XUS_GetWindowW(tls)
	(*US_WindowRec)(unsafe.Pointer(win)).Fh = XUS_GetWindowH(tls)
	(*US_WindowRec)(unsafe.Pointer(win)).Fpx = XUS_GetPrintX(tls)
	(*US_WindowRec)(unsafe.Pointer(win)).Fpy = XUS_GetPrintY(tls)
}

//	US_RestoreWindow() - Sets the current window parms to those held in the record

func XUS_RestoreWindow(tls *libc.TLS, win uintptr) {
	XUS_SetWindowX(tls, (*US_WindowRec)(unsafe.Pointer(win)).Fx)
	XUS_SetWindowY(tls, (*US_WindowRec)(unsafe.Pointer(win)).Fy)
	XUS_SetWindowW(tls, (*US_WindowRec)(unsafe.Pointer(win)).Fw)
	XUS_SetWindowH(tls, (*US_WindowRec)(unsafe.Pointer(win)).Fh)
	XUS_SetPrintX(tls, (*US_WindowRec)(unsafe.Pointer(win)).Fpx)
	XUS_SetPrintY(tls, (*US_WindowRec)(unsafe.Pointer(win)).Fpy)
}

