func XUSL_HandleComm(tls *libc.TLS, command int32) {
	switch command {
	case int32(US_Comm_EndGame): /* end game */
		Xload_game_error = int32(1)
		return
	case int32(US_Comm_Quit): /* quit */
		Xquit_to_dos = int32(1)
		return
	case int32(US_Comm_NewEasyGame): /* easy game */
		Xck_startingDifficulty = int32(D_Easy)
		return
	case int32(US_Comm_NewNormalGame): /* normal game */
		Xck_startingDifficulty = int32(D_Normal)
		return
	case int32(US_Comm_NewHardGame): /* hard game */
		Xck_startingDifficulty = int32(D_Hard)
		return
	case int32(US_Comm_ReturnToGame):
		fallthrough
	case int32(4): /* return to game, ? */
		return
	default:
		XQuit(tls, __ccgo_ts+7734) /* quit */
	}
}

