// C documentation
//
//	// Check if all the game files are present.
func XCK4_IsPresent(tls *libc.TLS) (r uint8) {
	// User-provided files
	if !(XFS_IsKeenFilePresent(tls, __ccgo_ts+14660) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsKeenFilePresent(tls, __ccgo_ts+14673) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsKeenFilePresent(tls, __ccgo_ts+14686) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	// Omnispeak-provided files
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14696) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14708) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14720) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14733) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	// Map header file may include the tile info
	//if (!FS_IsOmniFilePresent("TILEINFO.CK4"))
	//	return false;
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14745) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14758) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+14771) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	if !(XFS_IsOmniFilePresent(tls, __ccgo_ts+506) != 0) {
		return libc.BoolUint8(false1 != 0)
	}
	// We clearly have all of the required files.
	return libc.BoolUint8(true1 != 0)
}

/*
 * Spawn an enemy projectile
 * Note that the behaviour is slightly different from DOS Keen
 * DOS Keen SpawnEnemyShot returns 0 if shot is spawned, or -1 otherwise
 * omnispeak CK4_SpawnEnemyShot returns pointer if succesful, NULL otherwise
 */

func XCK4_SpawnEnemyShot(tls *libc.TLS, posX int32, posY int32, action uintptr) (r uintptr) {
	var new_object uintptr
	_ = new_object
	new_object = XCK_GetNewObj(tls, libc.BoolUint8(true1 != 0))
	if !(new_object != 0) {
		return libc.UintptrFromInt32(0)
	}
	(*CK_object)(unsafe.Pointer(new_object)).FposX = libc.Uint16FromInt32(posX)
	(*CK_object)(unsafe.Pointer(new_object)).FposY = libc.Uint16FromInt32(posY)
	(*CK_object)(unsafe.Pointer(new_object)).Ftype1 = int16(CT4_EnemyShot)
	(*CK_object)(unsafe.Pointer(new_object)).Factive = int32(OBJ_EXISTS_ONLY_ONSCREEN)
	XCK_SetAction(tls, new_object, action)
	if XCK_NotStuckInWall(tls, new_object) != 0 {
		return new_object
	} else {
		XCK_RemoveObj(tls, new_object)
		return libc.UintptrFromInt32(0)
	}
	return r
}

