func XCK_DrawStarWars(tls *libc.TLS) {
	// Keen5 sets the palette to the default one here.
	XVL_ClearScreen(tls, 0)
	XVL_SetScrollCoords(tls, 0, 0)
	XCA_SetGrPurge(tls)
	// Cache and set the Star Wars font.
	XCA_CacheGrChunk(tls, int32(5))
	XUS_SetPrintFont(tls, int16(2))
	// Render out the story text (to an offscreen buffer?)
	XCK_DrawSWText(tls)
	// Restore the font.
	XUS_SetPrintFont(tls, 0)
	XCA_CacheGrChunk(tls, int32(XCK_VAR_GetInt(tls, __ccgo_ts+16925, 0))) // Story bkg image.
	// Keen draws this to a separate surface, for fast copies.
	XVH_DrawBitmap(tls, 0, 0, int32(XCK_VAR_GetInt(tls, __ccgo_ts+16925, 0)))
	XVL_SetPaletteFromArray(tls, XCK_VAR_GetIntArray(tls, __ccgo_ts+16938))
	// At this point, Keen generates a set of buffers full of machine code,
	// one per line, which scale the text (from the surface mentioned above)
	// to make the "Star Wars" effect. (BuildScalers/CompileSWUpdate)
	// Instead, we just precalculate the various scaling factors.
	XCK_PrepareSWUpdate(tls)
	// ...and scroll the text!
	if !(XIN_GetLastScan(tls) != 0) {
		XStartMusic(tls, int16(XCK_VAR_GetInt(tls, __ccgo_ts+16957, 0)))
		XCK_ScrollSWText(tls)
		XStopMusic(tls)
	}
	XVL_DestroySurface(tls, Xck_starWarsTextSurface)
	XVL_ClearScreen(tls, 0)
	XVL_SetScrollCoords(tls, 0, 0)
	XVL_SetDefaultPalette(tls)
	XCA_ClearMarks(tls)
	XCK_HandleDemoKeys(tls)
}

func XCK_ShowTitleScreen(tls *libc.TLS) {
	// scrollofs = 0;
	XCA_CacheGrChunk(tls, int32(XCK_VAR_GetInt(tls, __ccgo_ts+16841, 0)))
	XVH_DrawBitmap(tls, 0, 0, int32(XCK_VAR_GetInt(tls, __ccgo_ts+16841, 0)))
	// Draw to offscreen buffer and copy?
	// VW_SetScreen(0,bufferofs_0);
	XVL_SetScrollCoords(tls, 0, 0)
	XVL_UpdateRect(tls, 0, 0, libc.Int32FromInt32(42)*libc.Int32FromInt32(8), int32(224))
	XVL_Present(tls)
	XIN_UserInput(tls, int32(420), libc.BoolUint8(false1 != 0))
	XCA_ClearMarks(tls)
	XCK_HandleDemoKeys(tls)
	XVL_Present(tls)
}

