const CK_MAX_DOOR_HEIGHT = 50

// This file contains some object functions (think, etc) which are common to
// several episodes.
// AFAIK, There never was a "ck_obj.c" in the DOS source

// The maximum height of a gem door. Note that this is the height of the
// _full_ door, including the two ground tiles, not just the main portion
// stored in user1.

func XCK_DoorOpen(tls *libc.TLS, obj uintptr) {
	bp := tls.Alloc(112)
	defer tls.Free(112)
	var i int32
	var _ /* tilesToReplace at bp+0 */ [50]uint16_t
	_ = i
	if int32((*CK_object)(unsafe.Pointer(obj)).Fuser1)+int32(2) > int32(CK_MAX_DOOR_HEIGHT) {
		XQuit(tls, __ccgo_ts+19424)
	}
	i = 0
	for {
		if !(i < int32((*CK_object)(unsafe.Pointer(obj)).Fuser1)+int32(2)) {
			break
		}
		(**(**[50]uint16_t)(__ccgo_up(bp)))[i] = libc.Uint16FromInt32(libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FposX), int16(libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FposY)+i), int16(1))) + int32(1))
		goto _1
	_1:
		;
		i = i + 1
	}
	XRF_ReplaceTiles(tls, bp, int32(1), libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FposX), libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FposY), int32(1), int32((*CK_object)(unsafe.Pointer(obj)).Fuser1)+int32(2))
}

