	(*CK_object)(unsafe.Pointer(obj)).Fuser3 = int16(libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FgfxChunk) + int32(2))
	XCK_SetAction(tls, obj, XCK_GetActionByName(tls, __ccgo_ts+19439))
