// C documentation
//
//	// Note that Keen 5 was the only keen to have the purple parameter, but
//	// it is added here for the other Keens in order to reuse code
func XCK_SpawnAxisPlatform(tls *libc.TLS, tileX int32, tileY int32, direction int32, purple uint8) {
	var obj uintptr
	var v1, v2, v3 int32
	_, _, _, _ = obj, v1, v2, v3
	obj = XCK_GetNewObj(tls, libc.BoolUint8(false1 != 0))
	if (*CK_EpisodeDef)(unsafe.Pointer(Xck_currentEpisode)).Fep == int32(EP_CK4) {
		v1 = int32(CT4_Platform)
	} else {
		if (*CK_EpisodeDef)(unsafe.Pointer(Xck_currentEpisode)).Fep == int32(EP_CK5) {
			v2 = int32(CT5_Platform)
		} else {
			if (*CK_EpisodeDef)(unsafe.Pointer(Xck_currentEpisode)).Fep == int32(EP_CK6) {
				v3 = int32(CT6_Platform)
			} else {
				v3 = int32(CT_Nothing)
			}
			v2 = v3
		}
		v1 = v2
	}
	(*CK_object)(unsafe.Pointer(obj)).Ftype1 = int16(v1)
	(*CK_object)(unsafe.Pointer(obj)).Factive = int32(OBJ_ALWAYS_ACTIVE)
	(*CK_object)(unsafe.Pointer(obj)).FzLayer = 0
	(*CK_object)(unsafe.Pointer(obj)).FposX = libc.Uint16FromInt32(tileX << libc.Int32FromInt32(G_T_SHIFT))
	(*CK_object)(unsafe.Pointer(obj)).FposY = libc.Uint16FromInt32(tileY << libc.Int32FromInt32(G_T_SHIFT))
	switch direction {
	case 0:
		(*CK_object)(unsafe.Pointer(obj)).FxDirection = 0
		(*CK_object)(unsafe.Pointer(obj)).FyDirection = int16(-int32(1))
	case int32(1):
		(*CK_object)(unsafe.Pointer(obj)).FxDirection = int16(1)
		(*CK_object)(unsafe.Pointer(obj)).FyDirection = 0
	case int32(2):
		(*CK_object)(unsafe.Pointer(obj)).FxDirection = 0
		(*CK_object)(unsafe.Pointer(obj)).FyDirection = int16(1)
	case int32(3):
		(*CK_object)(unsafe.Pointer(obj)).FxDirection = int16(-int32(1))
		(*CK_object)(unsafe.Pointer(obj)).FyDirection = 0
		break
	}
	XCK_SetAction(tls, obj, XCK_GetActionByName(tls, __ccgo_ts+11961))
	// TODO: These should *not* be done here.
	(*CK_object)(unsafe.Pointer(obj)).FgfxChunk = libc.Uint16FromInt16((*CK_action)(unsafe.Pointer((*CK_object)(unsafe.Pointer(obj)).FcurrentAction)).FchunkLeft)
	XCA_CacheGrChunk(tls, libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FgfxChunk))
	// CK_ResetClipRects(obj);
}

func XCK_AxisPlatform(tls *libc.TLS, obj uintptr) {
	var nextPosTile, nextPosUnit uint16_t
	_, _ = nextPosTile, nextPosUnit
	if Xck_nextX != 0 || Xck_nextY != 0 {
		return
	}
	//TODO: Implement properly.
	Xck_nextX = int16(int32((*CK_object)(unsafe.Pointer(obj)).FxDirection) * int32(12) * libc.Int32FromUint16(XSD_GetSpriteSync(tls)))
	Xck_nextY = int16(int32((*CK_object)(unsafe.Pointer(obj)).FyDirection) * int32(12) * libc.Int32FromUint16(XSD_GetSpriteSync(tls)))
	if int32((*CK_object)(unsafe.Pointer(obj)).FxDirection) == int32(1) {
		nextPosUnit = libc.Uint16FromInt32(libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FunitX2) + int32(Xck_nextX))
		nextPosTile = libc.Uint16FromInt32(libc.Int32FromUint16(nextPosUnit) >> libc.Int32FromInt32(G_T_SHIFT))
		if libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileX2) != libc.Int32FromUint16(nextPosTile) && libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16(nextPosTile), libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileY1), int16(2))) == int32(0x1F) {
			(*CK_object)(unsafe.Pointer(obj)).FxDirection = int16(-int32(1))
			//TODO: Change DeltaVelocity
			Xck_nextX = int16(int32(Xck_nextX) - libc.Int32FromUint16(nextPosUnit)&libc.Int32FromInt32(255))
		}
	} else {
		if int32((*CK_object)(unsafe.Pointer(obj)).FxDirection) == -int32(1) {
			nextPosUnit = libc.Uint16FromInt32(libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FunitX1) + int32(Xck_nextX))
			nextPosTile = libc.Uint16FromInt32(libc.Int32FromUint16(nextPosUnit) >> libc.Int32FromInt32(G_T_SHIFT))
			if libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileX1) != libc.Int32FromUint16(nextPosTile) && libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16(nextPosTile), libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileY1), int16(2))) == int32(0x1F) {
				(*CK_object)(unsafe.Pointer(obj)).FxDirection = int16(1)
				//TODO: Change DeltaVelocity
				//CK_PhysUpdateX(obj, 256 - nextPosUnit&255);
				Xck_nextX = int16(int32(Xck_nextX) + (libc.Int32FromInt32(256)-libc.Int32FromUint16(nextPosUnit))&libc.Int32FromInt32(255))
			}
		} else {
			if int32((*CK_object)(unsafe.Pointer(obj)).FyDirection) == int32(1) {
				nextPosUnit = libc.Uint16FromInt32(libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FunitY2) + int32(Xck_nextY))
				nextPosTile = libc.Uint16FromInt32(libc.Int32FromUint16(nextPosUnit) >> libc.Int32FromInt32(G_T_SHIFT))
				if libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileY2) != libc.Int32FromUint16(nextPosTile) && libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileX1), libc.Int16FromUint16(nextPosTile), int16(2))) == int32(0x1F) {
					if libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileX1), int16(libc.Int32FromUint16(nextPosTile)-int32(2)), int16(2))) == int32(0x1F) {
						//Stop the platform.
						(*CK_object)(unsafe.Pointer(obj)).Fvisible = libc.BoolUint8(true1 != 0)
						Xck_nextY = 0
					} else {
						(*CK_object)(unsafe.Pointer(obj)).FyDirection = int16(-int32(1))
						//TODO: Change DeltaVelocity
						Xck_nextY = int16(int32(Xck_nextY) - libc.Int32FromUint16(nextPosUnit)&libc.Int32FromInt32(255))
					}
				}
			} else {
				if int32((*CK_object)(unsafe.Pointer(obj)).FyDirection) == -int32(1) {
					nextPosUnit = libc.Uint16FromInt32(libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FunitY1) + int32(Xck_nextY))
					nextPosTile = libc.Uint16FromInt32(libc.Int32FromUint16(nextPosUnit) >> libc.Int32FromInt32(G_T_SHIFT))
					if libc.Int32FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileY1) != libc.Int32FromUint16(nextPosTile) && libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileX1), libc.Int16FromUint16(nextPosTile), int16(2))) == int32(0x1F) {
						if libc.Int32FromUint16(XCA_TileAtPos(tls, libc.Int16FromUint16((*CK_object)(unsafe.Pointer(obj)).FclipRects.FtileX1), int16(libc.Int32FromUint16(nextPosTile)+int32(2)), int16(2))) == int32(0x1F) {
							// Stop the platform.
							(*CK_object)(unsafe.Pointer(obj)).Fvisible = libc.BoolUint8(true1 != 0)
							Xck_nextY = 0
						} else {
							(*CK_object)(unsafe.Pointer(obj)).FyDirection = int16(1)
							//TODO: Change DeltaVelocity
							Xck_nextY = int16(int32(Xck_nextY) + (libc.Int32FromInt32(256) - libc.Int32FromUint16(nextPosUnit)&libc.Int32FromInt32(255)))
						}
					}
				}
			}
		}
	}
}

