func XCK_MapLevelMarkAsDone(tls *libc.TLS) {
	var flags, i, level, w, x, y int32
	var pw uintptr
	_, _, _, _, _, _, _ = flags, i, level, pw, w, x, y
	i = 0
	pw = XCA_TilePtrAtPos(tls, 0, 0, int16(2)) /* info layer */
	/* Look through the map for level-related tiles */
	y = 0
	for {
		if !(y < libc.Int32FromUint16(XCA_GetMapHeight(tls))) {
			break
		}
		x = 0
		for {
			if !(x < libc.Int32FromUint16(XCA_GetMapWidth(tls))) {
				break
			}
			w = libc.Int32FromUint16(**(**uint16_t)(__ccgo_up(pw)))
			level = w & int32(0xFF)
			if int64(level) >= XCK_VAR_GetInt(tls, __ccgo_ts+20163, int64(1)) && int64(level) <= XCK_VAR_GetInt(tls, __ccgo_ts+20179, int64(17)) && **(**uint16_t)(__ccgo_up(uintptr(unsafe.Pointer(&Xck_gameState)) + 4 + uintptr(level)*2)) != 0 {
				/* Is this a level tile */
				flags = w >> int32(8)
				/* Set the info tile at this position to 0 */
				**(**uint16_t)(__ccgo_up(pw)) = uint16(0)
				if flags == int32(0xD0) {
					/* If this is a 'blocking' part of the level */
					/* Set the foreground tile at this position to 0 also (remove the fences) */
					XCA_SetTileAtPos(tls, int16(x), int16(y), int16(1), uint16(0))
				} else {
					if flags == int32(0xF0) {
						/* If this is the flag holder for the level */
						if (*CK_EpisodeDef)(unsafe.Pointer(Xck_currentEpisode)).Fep != int32(EP_CK5) && ck_lastLevelFinished == level {
							XCK_FlippingFlagSpawn(tls, x, y)
						} else {
							XCK_MapFlagSpawn(tls, x, y)
						}
					}
				}
			}
			goto _2
		_2:
			;
			x = x + 1
			pw += 2
			i = i + 1
		}
		goto _1
	_1:
		;
		y = y + 1
	}
}

