func XCK_LoadLevel(tls *libc.TLS, doCache uint8, silent uint8) {
	if XIN_DemoGetMode(tls) != int32(IN_Demo_Off) {
		// If we're recording or playing back a demo, the game needs
		// to be deterministic. Seed the RNG at 0 and set difficulty
		// to normal.
		XUS_InitRndT(tls, libc.BoolUint8(false1 != 0))
		Xck_gameState.Fdifficulty = int32(D_Normal)
	} else {
		XUS_InitRndT(tls, libc.BoolUint8(true1 != 0))
	}
	if Xus_aslevFilename != 0 {
		XCA_CacheMapFromASLEV(tls, int32(Xck_gameState.FcurrentLevel), Xus_aslevFilename)
	} else {
		XCA_CacheMap(tls, int32(Xck_gameState.FcurrentLevel))
	}
	XRF_NewMap(tls)
	XCA_ClearMarks(tls)
	XCK_SetupObjArray(tls) // This is done inside ScanInfoLayer in CK4
	(*(*func(*libc.TLS))(unsafe.Pointer(&struct{ uintptr }{(*CK_EpisodeDef)(unsafe.Pointer(Xck_currentEpisode)).FscanInfoLayer})))(tls)
	if int32(Xca_mapOn) == 0 {
		XCK_MapLevelMarkAsDone(tls)
	}
	XRF_MarkTileGraphics(tls)
	//MM_BombOnError();
	XCA_LoadAllSounds(tls)
	// Cache Marked graphics and draw loading box
	if doCache != 0 {
		if Xck_inHighScores != 0 || silent != 0 {
			XCA_CacheMarks(tls, libc.UintptrFromInt32(0))
		} else {
			if XIN_DemoGetMode(tls) != int32(IN_Demo_Off) {
				XCA_CacheMarks(tls, XCK_VAR_GetString(tls, __ccgo_ts+20195, __ccgo_ts+20195))
			} else {
				XCA_CacheMarks(tls, XCK_VAR_GetStringArrayElement(tls, __ccgo_ts+20207, int32(Xca_mapOn)))
			}
		}
	}
	// CA_CacheMarks(0);
	if doCache != 0 && !(silent != 0) {
		XCK_BeginFadeDrawing(tls)
	}
}

