			XVHB_HLine(tls, XUS_GetWindowX(tls)+int32(4), XUS_GetWindowX(tls)+XUS_GetWindowW(tls)-int32(4), y+int32(1), clr)
			XVHB_HLine(tls, XUS_GetWindowX(tls)+int32(4), XUS_GetWindowX(tls)+XUS_GetWindowW(tls)-int32(4), y+int32(12), clr)
			XVHB_HLine(tls, XUS_GetWindowX(tls)+int32(4), XUS_GetWindowX(tls)+XUS_GetWindowW(tls)-int32(4), y+int32(13), clr)
			XVHB_VLine(tls, y+int32(1), y+int32(11), XUS_GetWindowX(tls)+int32(4), clr)
			XVHB_VLine(tls, y+int32(1), y+int32(11), XUS_GetWindowX(tls)+int32(5), clr)
			XVHB_VLine(tls, y+int32(1), y+int32(11), XUS_GetWindowX(tls)+XUS_GetWindowW(tls)-int32(4), clr)
			XVHB_VLine(tls, y+int32(1), y+int32(11), XUS_GetWindowX(tls)+XUS_GetWindowW(tls)-int32(5), clr)
			XVH_UpdateScreen(tls)
