// C documentation
//
//	// TODO: make this interoperable between episodes
func XCK_WallDebug(tls *libc.TLS) {
	bp := tls.Alloc(272)
	defer tls.Free(272)
	var i, i1, ti int32
	var _ /* buf at bp+0 */ [128]int8
	var _ /* buf at bp+128 */ [128]int8
	_, _, _ = i, i1, ti
	XVL_FixRefreshBuffer(tls)
	XUS_CenterWindow(tls, int32(24), int32(3))
	XUS_PrintCentered(tls, __ccgo_ts+20916)
	XVH_UpdateScreen(tls)
	// Cache the slope info foreground tiles
	i = libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles16m) + int32(0x6C)
	for {
		if !(i < libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles16m)+int32(0x6C)+int32(16)) {
			break
		}
		XCA_CacheGrChunk(tls, i)
		goto _1
	_1:
		;
		i = i + 1
	}
	// Draw the slope info tile over each foreground tile
	i1 = 0
	for {
		if !(i1 < libc.Int32FromUint16(Xca_gfxInfoE.FnumTiles16m)) {
			break
		}
		if Xca_graphChunks[i1+libc.Int32FromUint16(Xca_gfxInfoE.FoffTiles16m)] != 0 {
			ti = libc.Int32FromUint8(XTI_ForeTop(tls, libc.Uint16FromInt32(i1))) & int32(7)
			if ti != 0 {
				XCK_OverlayForegroundTile(tls, i1, ti+int32(0x6B))
			}
			ti = libc.Int32FromUint8(XTI_ForeBottom(tls, libc.Uint16FromInt32(i1))) & int32(7)
			if ti != 0 {
				XCK_OverlayForegroundTile(tls, i1, ti+int32(0x73))
			}
			ti = libc.Int32FromUint8(XTI_ForeRight(tls, libc.Uint16FromInt32(i1))) & int32(7)
			if ti > int32(1) {
				libc.Xsprintf(tls, bp, __ccgo_ts+20924, libc.VaList(bp+264, i1))
				XQuit(tls, bp)
			} else {
				if ti == int32(1) {
					XCK_OverlayForegroundTile(tls, i1, ti+int32(0x72))
				}
			}
			ti = libc.Int32FromUint8(XTI_ForeLeft(tls, libc.Uint16FromInt32(i1))) & int32(7)
			if ti > int32(1) {
				libc.Xsprintf(tls, bp+128, __ccgo_ts+20964, libc.VaList(bp+264, i1))
				XQuit(tls, bp+128)
			} else {
				if ti == int32(1) {
					XCK_OverlayForegroundTile(tls, i1, ti+int32(0x7A))
				}
			}
		}
		goto _2
	_2:
		;
		i1 = i1 + 1
	}
	// Hack to work around F10-Y not updating the screen immediately.
	XRF_Reposition(tls, Xrf_scrollXUnit, Xrf_scrollYUnit)
}

