func XCK_HandleInput(tls *libc.TLS) {
	XIN_ReadControls(tls, 0, uintptr(unsafe.Pointer(&Xck_inputFrame)))
	if Xck_inputFrame.FyDirection != -int32(1) {
		Xck_keenState.FkeenSliding = libc.BoolUint8(false1 != 0)
	}
	if !(Xck_gamePadEnabled != 0) || XIN_DemoGetMode(tls) != int32(IN_Demo_Off) {
		// Two button firing mode is used for demo playback
		if !(Xck_twoButtonFiring != 0) && XIN_DemoGetMode(tls) == int32(IN_Demo_Off) {
			Xck_keenState.FjumpIsPressed = Xck_inputFrame.Fjump
			Xck_keenState.FpogoIsPressed = Xck_inputFrame.Fpogo
			Xck_keenState.FshootIsPressed = Xck_inputFrame.Fbutton2
			if !(Xck_keenState.FjumpIsPressed != 0) {
				Xck_keenState.FjumpWasPressed = libc.BoolUint8(false1 != 0)
			}
			if !(Xck_keenState.FpogoIsPressed != 0) {
				Xck_keenState.FpogoWasPressed = libc.BoolUint8(false1 != 0)
			}
			if !(Xck_keenState.FshootIsPressed != 0) {
				Xck_keenState.FshootWasPressed = libc.BoolUint8(false1 != 0)
			}
		} else {
			// Check for two-button firing
			if Xck_inputFrame.Fjump != 0 && Xck_inputFrame.Fpogo != 0 {
				Xck_keenState.FshootIsPressed = libc.BoolUint8(true1 != 0)
				Xck_keenState.FjumpIsPressed = libc.BoolUint8(false1 != 0)
				Xck_keenState.FpogoIsPressed = libc.BoolUint8(false1 != 0)
				Xck_keenState.FjumpWasPressed = libc.BoolUint8(false1 != 0)
				Xck_keenState.FpogoWasPressed = libc.BoolUint8(false1 != 0)
				return
			}
			Xck_keenState.FshootWasPressed = libc.BoolUint8(false1 != 0)
			Xck_keenState.FshootIsPressed = libc.BoolUint8(false1 != 0)
			if Xck_inputFrame.Fjump != 0 {
				Xck_keenState.FjumpIsPressed = libc.BoolUint8(true1 != 0)
			} else {
				Xck_keenState.FjumpWasPressed = libc.BoolUint8(false1 != 0)
				Xck_keenState.FjumpIsPressed = libc.BoolUint8(false1 != 0)
			}
			if Xck_inputFrame.Fpogo != 0 {
				// Here be dragons!
				// In order to better emulate the original trilogy's controls, a delay
				// is introduced when pogoing in two-button firing.
				if Xck_pogoTimer <= int32(8) {
					Xck_pogoTimer = Xck_pogoTimer + libc.Int32FromUint16(XSD_GetSpriteSync(tls))
				} else {
					Xck_keenState.FpogoIsPressed = libc.BoolUint8(true1 != 0)
				}
			} else {
				// If the player lets go of pogo, pogo immediately.
				if Xck_pogoTimer != 0 {
					Xck_keenState.FpogoIsPressed = libc.BoolUint8(true1 != 0)
				} else {
					Xck_keenState.FpogoWasPressed = libc.BoolUint8(false1 != 0)
					Xck_keenState.FpogoIsPressed = libc.BoolUint8(false1 != 0)
				}
				Xck_pogoTimer = 0
			}
		}
	} else {
		// TODO: Gravis Gamepad input handling
	}
}

