func XCK_ShowStatusWindow(tls *libc.TLS) {
	var screen uintptr
	_ = screen
	// int oldBufferofs;
	XUS_SetWindowX(tls, 0)
	XUS_SetWindowW(tls, int32(320))
	XUS_SetWindowY(tls, 0)
	XUS_SetWindowH(tls, int32(200))
	// This function is called when enter pressed; check for A+2 to enable debug mode
	if XIN_GetKeyState(tls, uint8(IN_SC_A)) != 0 && XIN_GetKeyState(tls, uint8(IN_SC_Two)) != 0 {
		XUS_CenterWindow(tls, int32(20), int32(2))
		XUS_SetPrintY(tls, XUS_GetPrintY(tls)+int32(2))
		XUS_Print(tls, XCK_VAR_GetString(tls, __ccgo_ts+21724, __ccgo_ts+21724))
		XVH_UpdateScreen(tls)
		XIN_WaitButton(tls)
		Xck_debugActive = libc.BoolUint8(true1 != 0)
	}
	XRF_Refresh(tls)
	// Clear out all animating tiles
	XRFL_SetupOnscreenAnimList(tls)
	// Draw the status window to scratch area in the buffer
	// Omnispeak: make a surface and set it as the screen, temporarily,
	// in order to use the VH_ functions for drawing
	screen = Xvl_emuegavgaadapter.Fscreen
	XVL_SurfaceToSurface(tls, screen, Xck_statusSurface, 0, 0, 0, 0, libc.Int32FromInt32(RF_BUFFER_WIDTH_TILES)<<libc.Int32FromInt32(4), libc.Int32FromInt32(STATUS_H)+libc.Int32FromInt32(16))
	// And save a copy of the screen as-is to a backup surface as well.
	XVL_SurfaceToSurface(tls, screen, Xck_backupSurface, 0, 0, 0, 0, libc.Int32FromInt32(RF_BUFFER_WIDTH_TILES)<<libc.Int32FromInt32(4), libc.Int32FromInt32(RF_BUFFER_HEIGHT_TILES)<<libc.Int32FromInt32(4))
	XVL_SetScreen(tls, Xck_statusSurface)
	//int oldScrollX = VL_GetScrollX();
	//int oldScrollY = VL_GetScrollY();
	XCK_DrawStatusWindow(tls)
	//VL_SetScrollCoords(oldScrollX, oldScrollY);
	XVL_SetScreen(tls, screen)
	// bufferofs = oldBufferofs;
	XRF_Refresh(tls)
	// Scroll the window down
	XSD_PlaySound(tls, int16(XCK_VAR_GetInt(tls, __ccgo_ts+21747, 0)))
	Xck_statusWindowYPx = int32(16)
	Xck_statusDown = libc.BoolUint8(false1 != 0)
	XRF_SetDrawFunc(tls, __ccgo_fp(XCK_ScrollStatusWindow))
	for cond := true; cond; cond = int32(1) != 0 {
		XRF_Refresh(tls)
		if Xck_statusWindowYPx == int32(168) {
			break
		}
		Xck_statusWindowYPx = Xck_statusWindowYPx + libc.Int32FromUint16(XSD_GetSpriteSync(tls))*int32(8)
		if Xck_statusWindowYPx <= int32(168) {
			continue
		}
		Xck_statusWindowYPx = int32(168)
	}
	XRF_Refresh(tls)
	XRF_SetDrawFunc(tls, libc.UintptrFromInt32(0))
	XIN_ClearKeysDown(tls)
	XIN_WaitButton(tls) //IN_Ack();
	// Scroll the window up
	XSD_PlaySound(tls, int16(XCK_VAR_GetInt(tls, __ccgo_ts+21764, 0)))
	Xck_statusWindowYPx = Xck_statusWindowYPx - int32(16)
	Xck_statusDown = libc.BoolUint8(true1 != 0)
	XRF_SetDrawFunc(tls, __ccgo_fp(XCK_ScrollStatusWindow))
	for cond := true; cond; cond = int32(1) != 0 {
		XRF_Refresh(tls)
		if Xck_statusWindowYPx == 0 {
			break
		}
		Xck_statusWindowYPx = Xck_statusWindowYPx - libc.Int32FromUint16(XSD_GetSpriteSync(tls))*int32(8)
		if Xck_statusWindowYPx >= 0 {
			continue
		}
		Xck_statusWindowYPx = 0
	}
	XRF_SetDrawFunc(tls, libc.UintptrFromInt32(0))
	(*CK_object)(unsafe.Pointer(Xck_scoreBoxObj)).FposX = uint16(0)
}

